const setSESTenantStatus = `-- name: SetSESTenantStatus :one
WITH prev AS (
    SELECT sending_status FROM ses_tenants
    WHERE workspace_id = $8 AND inbox_id = $9
    FOR UPDATE
)
UPDATE ses_tenants t SET sending_status = $1, customer_status = $2,
    aws_status = $3, cause = $4, reputation_impact = $5,
    status_at = $6, checked_at = $7
FROM prev
WHERE t.workspace_id = $8 AND t.inbox_id = $9
RETURNING prev.sending_status AS previous_status
`

type SetSESTenantStatusParams struct {
	SendingStatus    string
	CustomerStatus   *string
	AwsStatus        *string
	Cause            *string
	ReputationImpact string
	StatusAt         *time.Time
	Now              *time.Time
	WorkspaceID      uuid.UUID
	InboxID          uuid.UUID
}

func (q *Queries) SetSESTenantStatus(ctx context.Context, arg SetSESTenantStatusParams) (string, error) {
	row := q.db.QueryRow(ctx, setSESTenantStatus,
		arg.SendingStatus,
		arg.CustomerStatus,
		arg.AwsStatus,
		arg.Cause,
		arg.ReputationImpact,
		arg.StatusAt,
		arg.Now,
		arg.WorkspaceID,
		arg.InboxID,
	)
	var previous_status string
	err := row.Scan(&previous_status)
	return previous_status, err
}
